import{t as e}from"./framework~index~page~page~page~page~layout~not-found~page~page~page~page~app-page-cache-ren~ilpl4ewo-C5idnugW.js";import{n as t,r as n,t as r}from"./site-frame-BCDeRG8F.js";import{a as i}from"./site-content-DW4ypza8.js";var a=e(),o={title:`Merchant Payment Questions Answered | TSC Insights`,description:`Twenty practical payment concepts covering interchange, pricing, Level 2 and Level 3 data, ACH, ERP integrations, AR and AP automation, security, statements, and freight.`,alternates:{canonical:`${i}/insights`}},s=[{category:`Card costs`,question:`What is interchange?`,answer:`Interchange is the underlying fee generally paid to the cardholder’s issuing bank when a card transaction is processed. It is only one part of total acceptance cost. TSC separates interchange, network fees, and provider markup so you can see what is actually driving expense.`,href:`/services/interchange-optimization`},{category:`Card costs`,question:`Is interchange the same as processor markup?`,answer:`No. Interchange and card brand assessments are established within the card ecosystem, while processor markup is the provider’s added pricing. A proposal should separate them clearly. TSC normalizes statements and proposals so merchants can compare like for like.`,href:`/services/merchant-statement-review`},{category:`Pricing`,question:`What does effective rate tell me?`,answer:`Effective rate is total processing cost divided by card volume. It is a useful directional measure, but it does not explain card mix, qualification, software charges, or one-time fees. TSC uses it as a starting point, then investigates the transaction-level causes.`,href:`/services/merchant-statement-review`},{category:`Pricing`,question:`Which pricing model is best?`,answer:`Interchange plus is often the most transparent, while flat-rate, tiered, and subscription models can be appropriate in certain environments. The right answer depends on volume, ticket size, card mix, channels, and operational needs. TSC models the full cost before recommending a structure.`,href:`/services/payment-processing-ach`},{category:`Qualification`,question:`Why do transactions downgrade?`,answer:`A transaction can qualify at a higher cost when required data is missing, submitted late, or passed incorrectly. Card type, authorization, settlement timing, entry method, and gateway configuration may all matter. TSC traces the full data path to find preventable qualification gaps.`,href:`/services/level-2-level-3-processing`},{category:`Qualification`,question:`What are Level 2 and Level 3 data?`,answer:`They are additional transaction details, such as tax, invoice references, and line items, associated with eligible commercial-card programs. Visa’s US Commercial Enhanced Data Program (CEDP) now replaces its legacy Level 2/3 programs; Mastercard has its own requirements. TSC checks the network, card eligibility, data quality, and processor setup rather than assuming that extra fields guarantee lower fees.`,href:`/services/level-2-level-3-processing`},{category:`ACH`,question:`When should a business offer ACH?`,answer:`ACH may fit recurring payments, high-ticket invoices, and customers who prefer bank payments. It can reduce card expense, but authorization, returns, funding, fraud controls, and reconciliation still matter. TSC designs an adoption plan around customer behavior and cash flow.`,href:`/services/payment-processing-ach`},{category:`Infrastructure`,question:`What is the difference between a gateway and a merchant account?`,answer:`A gateway securely carries payment information and connects systems. A merchant account and acquiring relationship support authorization, settlement, and funding. They may be bundled or separate. TSC maps each party’s role so responsibility, pricing, and data flow are clear.`,href:`/services/payment-processing-ach`},{category:`Customer pricing`,question:`Are surcharging and cash discounting the same?`,answer:`No. They differ in how prices and card costs are presented and can involve different card brand, legal, disclosure, and operational requirements. Rules vary by program and location. TSC helps assess suitability and coordinates qualified compliance guidance before launch.`,href:`/contact`},{category:`Security`,question:`What does PCI compliance actually cover?`,answer:`PCI DSS is a security standard for environments that store, process, or transmit cardholder data. Compliance scope depends on how payments are accepted and which systems touch the data. TSC helps reduce exposure through sound architecture while the merchant retains its compliance responsibilities.`,href:`/contact`},{category:`Security`,question:`Why does tokenization matter?`,answer:`Tokenization replaces sensitive payment data with a non-sensitive reference that can support repeat billing and integrated workflows. Its portability and ownership vary by provider. TSC evaluates security, migration risk, customer experience, and long-term flexibility before a platform decision.`,href:`/services/erp-integrated-payments`},{category:`ERP integration`,question:`What should an ERP payment integration accomplish?`,answer:`A strong integration should reduce re-entry, improve posting and reconciliation, preserve useful payment data, and give teams better visibility. Connectivity alone is not the outcome. TSC starts with the operating problem, then validates what the integration can actually automate.`,href:`/services/erp-integrated-payments`},{category:`ERP integration`,question:`Is a payment hub the same as a gateway?`,answer:`Not necessarily. A gateway moves transaction data, while a payment hub may orchestrate multiple payment methods, processors, business systems, tokens, and workflows. Capabilities vary materially. TSC defines requirements first so the technology fits the business instead of dictating it.`,href:`/services/erp-integrated-payments`},{category:`Operations`,question:`How can payments reconcile automatically?`,answer:`Automation can connect invoice references, customer records, payment status, fees, deposits, and remittance data back to the accounting system. Exceptions still need ownership. TSC maps the desired posting logic and controls before recommending an integration.`,href:`/services/erp-integrated-payments`},{category:`Accounts receivable`,question:`What does AR automation improve?`,answer:`AR automation can streamline invoice delivery, payment acceptance, reminders, cash application, and reporting. The best opportunity depends on where staff lose time or visibility today. TSC reviews the current workflow and prioritizes improvements with measurable operational value.`,href:`/services/ar-ap-automation`},{category:`Accounts payable`,question:`What does AP automation improve?`,answer:`AP automation can connect invoice intake, approvals, payment execution, remittance, and reconciliation. Controls and supplier adoption are as important as technology. TSC helps design the workflow, evaluate providers, and coordinate implementation around the accounting environment.`,href:`/services/ar-ap-automation`},{category:`Accounts payable`,question:`How do virtual cards and rebates work?`,answer:`A virtual card uses a controlled card credential to pay an enrolled supplier. Eligible spend may generate revenue share, but economics depend on supplier acceptance, interchange, program terms, and payment mix. TSC evaluates the net value without overstating the rebate headline.`,href:`/services/ar-ap-automation`},{category:`Statements`,question:`What can a merchant statement review uncover?`,answer:`A review can identify pricing structure, provider markup, qualification patterns, card mix, ancillary fees, funding behavior, and unusual changes over time. One month may not tell the whole story. TSC combines statements with business context before making recommendations.`,href:`/services/merchant-statement-review`},{category:`Provider strategy`,question:`When should I consider changing processors?`,answer:`A switch may be warranted when cost, support, funding, reporting, integration, or contract limitations cannot be corrected. Changing solely for a quoted rate can create new problems. TSC first tests whether the current environment can be improved, then runs a disciplined comparison if needed.`,href:`/contact`},{category:`Freight`,question:`Can freight and payment strategy work together?`,answer:`Yes. Freight expense, customer delivery options, working capital, and payment workflows can affect the same operating margin. TSC can help merchants explore parcel and LTL options while keeping the commercial review connected to their broader payment and back-office strategy.`,href:`/services/freight-logistics`}],c=[{title:`Card costs and pricing`,categories:[`Card costs`,`Pricing`,`Qualification`,`Customer pricing`,`Statements`,`Provider strategy`]},{title:`Payment methods and security`,categories:[`ACH`,`Infrastructure`,`Security`]},{title:`Connected accounting and automation`,categories:[`ERP integration`,`Operations`,`Accounts receivable`,`Accounts payable`]},{title:`Freight and logistics`,categories:[`Freight`]}];function l(){return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n,{}),(0,a.jsxs)(`main`,{id:`main-content`,className:`seo-page`,children:[(0,a.jsx)(`section`,{className:`seo-hero insights-hero`,children:(0,a.jsxs)(`div`,{children:[(0,a.jsx)(`p`,{className:`eyebrow`,children:`Payment concepts explained`}),(0,a.jsx)(`h1`,{children:`Understand your payment options.`}),(0,a.jsx)(`p`,{children:`Twenty practical concepts, in plain language. Choose a question to read the answer.`})]})}),(0,a.jsx)(`section`,{className:`concept-groups`,children:c.map(e=>(0,a.jsxs)(`div`,{className:`concept-group`,children:[(0,a.jsx)(`h2`,{children:e.title}),s.filter(t=>e.categories.includes(t.category)).map(e=>(0,a.jsxs)(`details`,{children:[(0,a.jsx)(`summary`,{children:e.question}),(0,a.jsx)(`p`,{children:e.answer})]},e.question))]},e.title))}),(0,a.jsx)(r,{})]}),(0,a.jsx)(t,{})]})}export{l as default,o as metadata};